code:
def solve(intervals):
    if not intervals:
        return []
    # sort intervals by start
    intervals.sort(key=lambda x: x[0])
    merged = [intervals[0][:]]  # copy
    for cur in intervals[1:]:
        last = merged[-1]
        if cur[0] <= last[1]:  # overlap or touch
            last[1] = max(last[1], cur[1])
        else:
            merged.append(cur[:])
    return merged

