{"task_id": "T39", "code": "def solve(a, b):
    # Optimize memory by using only two rows of DP.
    # Ensure a is the shorter string for less space.
    if len(a) > len(b):
        a, b = b, a
    n, m = len(a), len(b)
    previous = list(range(n + 1))  # dp for a prefix of a vs empty b
    for j in range(1, m + 1):
        current = [j] + [0] * n
        bj = b[j - 1]
        for i in range(1, n + 1):
            if a[i - 1] == bj:
                cost = 0
            else:
                cost = 1
            # deletion (previous[i] + 1), insertion (current[i-1] + 1), substitution (previous[i-1] + cost)
            current[i] = min(previous[i] + 1, current[i - 1] + 1, previous[i - 1] + cost)
        previous = current
    return previous[n]"}

