def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Supports integers and +, -, *, / operators. Division truncates toward zero.
    """
    stack = []
    for t in tokens:
        if t.lstrip('-').isdigit():
            stack.append(int(t))
        else:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            elif t == '/':
                # truncate toward zero
                stack.append(int(a / b))
            else:
                raise ValueError('Invalid operator')
    return stack[0] if stack else 0

